/**
 * src/main.tsx: the entry point.
 *
 * Holds the tasks for this window, unless another window already does (then
 * it shows OtherWindow and opens nothing until USE HERE: store/instance.ts).
 * Opens the store (storage is read into memory first, so the first render
 * already has the user's tasks), registers the service worker in the built
 * app (offline and install, public/sw.js is generated by the build), then
 * renders the app. Any failure shows the crash screen (app/Crash.tsx).
 */
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

import { App } from './app/App';
import { CrashBoundary, CrashScreen } from './app/Crash';
import { OtherWindow } from './app/OtherWindow';
import { startStore } from './store';
import { askToStepAside, holdTasks, type Lease, onStepAside, waitForTasks } from './store/instance';
import { StoreProvider } from './store/react';
import './styles/theme.css';
import './styles/app.css';

// Registered first, so an update can still arrive even if this version fails to start.
if (import.meta.env.PROD && 'serviceWorker' in navigator) {
  void navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`).catch(() => undefined);
}

const root = createRoot(document.getElementById('root')!);

/** Opens the tasks in this window (it holds `lease`) and renders the app. */
async function open(lease: Lease): Promise<void> {
  try {
    const started = await startStore();
    // Another window asks for the tasks (its USE HERE): save everything, stop, let them go.
    const stopListening = onStepAside(() => {
      stopListening();
      root.render(<OtherWindow moved onUseHere={() => location.reload()} />);
      void started.close().finally(() => lease.release());
    });
    root.render(
      <StrictMode>
        <StoreProvider value={started.bundle}>
          <CrashBoundary bundle={started.bundle}>
            <App />
          </CrashBoundary>
        </StoreProvider>
      </StrictMode>,
    );
  } catch (error) {
    // The store couldn't start: say so (never a blank page).
    lease.release();
    root.render(<CrashScreen error={error} />);
  }
}

// One window at a time holds the tasks (store/instance.ts). Another window already has
// them: this one opens nothing until USE HERE, so the two never overwrite each other.
const lease = await holdTasks();
if (lease) await open(lease);
else
  root.render(
    <OtherWindow
      onUseHere={() => {
        askToStepAside();
        void waitForTasks().then(open);
      }}
    />,
  );
